#[test]
fn received_context_real_process_handoff_preserves_transitive_sources_without_replay(){
 let isolation=Fixture::new();let root=isolation.path.join("xdg");fs::create_dir(&root).unwrap();let helper=concat!(module_path!(),"::received_context_handoff_control").split_once("::").unwrap().1;let mut cmd=Command::new(std::env::current_exe().unwrap());cmd.args(["--exact",helper,"--ignored","--nocapture","--test-threads=1"]).env("COUCOU_MEMORY_HANDOFF_XDG",&root);
 for(key,name)in[("XDG_CONFIG_HOME","config"),("XDG_DATA_HOME","data"),("XDG_CACHE_HOME","cache")]{let path=root.join(name);fs::create_dir(&path).unwrap();cmd.env(key,path);}
 let log=isolation.path.join("control.log");let output=fs::OpenOptions::new().create_new(true).write(true).open(&log).unwrap();cmd.stdout(Stdio::from(output.try_clone().unwrap())).stderr(Stdio::from(output));let mut child=ChildGuard(cmd.spawn().unwrap());let until=Instant::now()+Duration::from_secs(90);let status=loop{if let Some(s)=child.0.try_wait().unwrap(){break s;}assert!(Instant::now()<until,"isolated received-data recovery timed out");std::thread::sleep(Duration::from_millis(10));};assert!(status.success(),"isolated native received-data handoff: {}",fs::read_to_string(log).unwrap());
}

